-- M10 智能任务编排：任务链（一对多）+ 候选组选机（多对多）+ 执行策略 + 队列管理。
-- 设计（对抗评审定稿）：wcs_task.app_id 保持 NOT NULL；链为独立表，段定义存链行 JSON，
-- 编排器选中设备后才物化子任务行（materialize-on-bind），子任务 task_no = chain_no + '-' + seq 确定性生成。

-- ===== 任务链 =====
create table if not exists "wcs_task_chain" (
    "id" bigint generated by default as identity primary key,
    "chain_no" varchar(128) not null,
    "upstream_app_id" bigint not null default 0,        -- 下发者（AppKey 验签身份；0=appkey 关闭旁路/管理端）
    "status" varchar(32) not null default 'pending',    -- pending/running/completed/failed/cancelled
    "segments" text not null default '[]',              -- JSON 数组 [{seq, appId?|candidateAppIds[], taskType, payload, 坐标可选}]
    "select_strategy" varchar(32) not null default 'idle_first',  -- 候选组选机策略：idle_first/round_robin
    "priority" bigint not null default 0,
    "payload" text not null default '{}',
    "wms_ref" varchar(256) not null default '',
    "error_message" varchar(1024) not null default '',
    "finish_time" timestamp(6),
    "version" bigint not null default 0,                -- 乐观锁：编排器推进 vs 管理端取消
    "creator" varchar(512) not null default '',
    "create_time" timestamp(6) not null default current_timestamp,
    "last_update_time" timestamp(6) not null default current_timestamp,
    "is_valid" boolean not null default true,
    "tenant_id" bigint not null default 1
);

-- 链号幂等键（H2 无 partial index：唯一索引含软删行，软删链的 chain_no 不复用，文档已声明）
create unique index if not exists "uk_wcs_task_chain_no" on "wcs_task_chain" ("tenant_id", "chain_no");
create index if not exists "idx_wcs_task_chain_status" on "wcs_task_chain" ("status");

-- ===== 任务表编排列 =====
alter table "wcs_task" add column if not exists "chain_id" bigint;
alter table "wcs_task" add column if not exists "seq_no" bigint;
alter table "wcs_task" add column if not exists "retry_count" bigint not null default 0;
alter table "wcs_task" add column if not exists "max_retry" bigint not null default 0;
-- 唯一索引（并发双物化兜底）：先查后插只保证单线程崩溃重放幂等，双编排线程（手动触发/多实例）
-- 需要 DB 层防重。PG/H2 对 NULL 视为彼此不同，存量独立任务（chain_id=NULL）不受影响。
create unique index if not exists "uk_wcs_task_chain_seq" on "wcs_task" ("chain_id", "seq_no");

-- ===== 应用：工作模式（队列暂停/维护）+ 派工策略 =====
alter table "wcs_application" add column if not exists "work_mode" varchar(32) not null default 'normal';
alter table "wcs_application" add column if not exists "dispatch_strategy" varchar(32) not null default 'priority';

-- ===== 字典 =====
